  unidad: ['unidad', 'um', 'unidadmedida', 'uom'],
  lead_time_dias: ['leadtimedias', 'leadtime', 'plazoentrega', 'diasentrega', 'tiempoentrega', 'plazodias'],
  lead_time_desv_dias: ['leadtimedesvdias', 'desvleadtime', 'desviacionleadtime'],
  moq: ['moq', 'minimocompra', 'cantidadminima', 'multiplo', 'pedidominimo'],
  en_transito: ['entransito', 'por recibir', 'pedidopendiente', 'ordenado', 'pendienterecibir', 'pedido en camino', 'ordenes abiertas'],
  fecha_llegada_transito: ['fechallegadatransito', 'fechaestimadallegada', 'fechallegada'],
  proveedor: ['proveedor', 'vendor', 'supplier'],
  activo: ['activo', 'estado', 'active'],
  motivo: ['motivo', 'razon', 'causa', 'observacion'],
  bodega: ['bodega', 'almacen', 'warehouse', 'ubicacion', 'sede'],
  vida_util_dias: ['vidautildias', 'vidautil', 'diasvencimiento'],
  documento: ['documento', 'numerodocumento', 'nrodocumento', 'factura', 'consecutivo'],
};

// Devuelve { campo: nombreDeColumnaReal }. El mapeo del usuario manda sobre la deteccion automatica.
function detectarColumnas(encabezados, mapeoUsuario, campos) {
  const porClave = new Map(encabezados.map((h) => [clave(h), h]));
  const out = {};
  const usadas = new Set();
  const manual = mapeoUsuario || {};
  for (const campo of campos) {
    if (manual[campo]) {
      const h = encabezados.find((x) => x === manual[campo]) || porClave.get(clave(manual[campo]));
      if (h) { out[campo] = h; usadas.add(h); continue; }
    }
    for (const sinonimo of SINONIMOS[campo] || [campo]) {
      const h = porClave.get(clave(sinonimo));
      if (h && !usadas.has(h)) { out[campo] = h; usadas.add(h); break; }
    }
  }
  // Segunda pasada: encabezados que contienen un sinonimo largo y especifico ("Plazo de entrega (dias)", "Existencia actual")
  for (const campo of campos) {
    if (out[campo]) continue;
    for (const sinonimo of (SINONIMOS[campo] || []).map(clave).filter((s) => s.length >= 8)) {
      const h = encabezados.find((x) => !usadas.has(x) && clave(x).includes(sinonimo));
      if (h) { out[campo] = h; usadas.add(h); break; }
    }
  }
  return out;
}

// ---------- tipos de movimiento ----------
// efecto sobre el saldo y papel en la demanda; solo 'salida' y 'devolucion_cliente' cuentan para la demanda
const EFECTO_TIPO = { entrada: 1, saldo_inicial: 1, devolucion_cliente: 1, ajuste_pos: 1, traslado_entrada: 1, salida: -1, devolucion_proveedor: -1, ajuste_neg: -1, traslado_salida: -1 };

function clasificarTipo(texto, cantidadConSigno) {
  const t = norm(texto);
  if (!t) return cantidadConSigno < 0 ? 'salida' : (cantidadConSigno > 0 ? 'entrada' : 'desconocido');
  if (/saldo inicial|inventario inicial|apertura|existencia inicial/.test(t)) return 'saldo_inicial';
  if (/devol/.test(t) && /(cliente|venta|consumidor)/.test(t)) return 'devolucion_cliente';
  if (/devol/.test(t) && /(proveedor|compra)/.test(t)) return 'devolucion_proveedor';
  if (/nota credito/.test(t)) return 'devolucion_cliente';
  if (/devol/.test(t)) return cantidadConSigno < 0 ? 'devolucion_proveedor' : 'devolucion_cliente';
  if (/(traslado|transferencia)/.test(t)) {
    if (/(entrada|ingreso|recib|destino)/.test(t)) return 'traslado_entrada';
    if (/(salida|egreso|origen|envio)/.test(t)) return 'traslado_salida';
    return cantidadConSigno < 0 ? 'traslado_salida' : 'traslado_entrada';
  }
  if (/ajuste|sobrante|faltante|merma|averia|dano|baja de|vencimiento|vencido|perdida|robo|conteo|toma fisica/.test(t)) {
    if (/(positiv|sobrante|\+|entrada|aumento)/.test(t)) return 'ajuste_pos';
    if (/(negativ|faltante|merma|averia|dano|baja|vencimiento|vencido|perdida|robo|-|salida)/.test(t)) return 'ajuste_neg';
    return cantidadConSigno < 0 ? 'ajuste_neg' : 'ajuste_pos';
  }
  if (/compra|entrada|ingreso|recepcion|recibo|produccion|importacion|reposicion|reintegro/.test(t)) return 'entrada';
  if (/venta|salida|consumo|despacho|egreso|remision|factura|requisicion|entrega|pedido cliente|gasto/.test(t)) return 'salida';
  return 'desconocido';
}

// ---------- normalizacion ----------
// filasMov y filasMae son listas de objetos (una fila por registro, como las entregan los nodos de lectura de n8n).
function normalizar(filasMov, filasMae, cfg) {
  const avisos = [];
  const calidad = { filas_movimientos: filasMov.length, filas_usadas: 0, descartadas: {}, duplicados_sospechosos: 0, skus_sin_maestro: [], granularidad_mensual: false };
  const descartar = (motivo) => { calidad.descartadas[motivo] = (calidad.descartadas[motivo] || 0) + 1; };
  const encMov = filasMov.length ? Object.keys(filasMov[0]) : [];
  const colMov = detectarColumnas(encMov, cfg.mapeo, ['fecha', 'sku', 'producto', 'tipo', 'cantidad', 'entrada', 'salida', 'costo_unitario', 'saldo', 'motivo', 'bodega', 'documento', 'lead_time_dias', 'stock_actual']);
  if (!colMov.fecha || !colMov.sku || !(colMov.cantidad || colMov.entrada || colMov.salida)) {
    return { error: `No se reconocieron las columnas minimas de movimientos (fecha, sku y cantidad). Columnas recibidas: ${encMov.slice(0, 12).join(', ') || 'ninguna'}. Indica el mapeo en la configuracion.`, avisos, calidad };
  }
  const sinTipo = !colMov.tipo;
  const separadas = !colMov.cantidad && (colMov.entrada || colMov.salida);
  if (sinTipo && !separadas) avisos.push('El archivo de movimientos no tiene columna de tipo: se usa el signo de la cantidad (negativo = salida). Si el sistema registra devoluciones, ajustes o traslados, agrega la columna de tipo o de motivo para que no se cuenten como demanda.');
  const bodegas = new Set();
  const movs = [];
  const vistos = new Map();
  filasMov.forEach((fila, idx) => {
    const f = parsearFecha(fila[colMov.fecha], cfg.formato_fecha);
    const sku = String(fila[colMov.sku] ?? '').trim();
    if (!f) { descartar('fecha invalida'); return; }
    if (!sku) { descartar('sin codigo de producto'); return; }
    const registros = [];
    if (separadas) {
      const e = colMov.entrada ? parsearNumero(fila[colMov.entrada]) : NaN;
      const s = colMov.salida ? parsearNumero(fila[colMov.salida]) : NaN;
      if (e > 0) registros.push(['entrada', e]);
      if (s > 0) registros.push(['salida', s]);
    } else {
      const q = parsearNumero(fila[colMov.cantidad]);
      if (!Number.isFinite(q)) { descartar('cantidad invalida'); return; }
      if (q === 0) { descartar('cantidad cero'); return; }
      registros.push([sinTipo ? (q < 0 ? 'salida' : 'entrada') : clasificarTipo(fila[colMov.tipo], q), q]);
    }
    for (const [tipo, q] of registros) {
      if (tipo === 'desconocido') { descartar(`tipo de movimiento no reconocido (${String(fila[colMov.tipo] ?? '').slice(0, 25)})`); continue; }
      const bodega = colMov.bodega ? String(fila[colMov.bodega] ?? '').trim() : '';
      if (bodega) bodegas.add(bodega);
      const saldo = colMov.saldo ? parsearNumero(fila[colMov.saldo]) : NaN;
      const costo = colMov.costo_unitario ? parsearNumero(fila[colMov.costo_unitario]) : NaN;
      const m = {
        idx, dia: f.dia, mensual: f.mensual, sku, producto: colMov.producto ? String(fila[colMov.producto] ?? '').trim() : '', tipo, cantidad: Math.abs(q),
        efecto: EFECTO_TIPO[tipo] * Math.abs(q), costo: Number.isFinite(costo) && costo > 0 ? costo : null, saldo: Number.isFinite(saldo) ? saldo : null,
        bodega, documento: colMov.documento ? String(fila[colMov.documento] ?? '') : '',
      };
      const k = `${m.dia}|${m.sku}|${m.tipo}|${m.cantidad}|${m.bodega}|${m.documento}`;
      vistos.set(k, (vistos.get(k) || 0) + 1);
      if (m.documento && vistos.get(k) > 1) { calidad.duplicados_sospechosos++; descartar('duplicado exacto con el mismo documento'); continue; }
      movs.push(m);
    }
  });
  const sospechosos = [...vistos.values()].filter((n) => n > 1).reduce((s, n) => s + n - 1, 0);
  calidad.duplicados_sospechosos += sospechosos;
  if (sospechosos && !movs.some((m) => m.documento)) avisos.push(`Filas de movimiento identicas (misma fecha, producto, tipo y cantidad): ${sospechosos}. El archivo no trae numero de documento, asi que pueden ser ventas repetidas legitimas o duplicados. No se eliminaron.`);
  calidad.filas_usadas = movs.length;
  if (movs.length && movs.filter((m) => m.mensual).length / movs.length > 0.5) {
    calidad.granularidad_mensual = true;
    avisos.push('Las fechas vienen por mes (AAAA-MM) y no por dia: no se puede reconstruir el saldo diario, asi que no se calculan los dias en cero ni los quiebres dentro del mes.');
  }
  const porBodega = !!cfg.por_bodega && bodegas.size > 1;
  if (bodegas.size > 1 && !porBodega) avisos.push(`El archivo trae ${bodegas.size} bodegas y se analizan sumadas por producto (el saldo por bodega no se usa). Para analizar cada bodega por separado activa por_bodega en la configuracion.`);
  const llave = (sku, bodega) => (porBodega ? `${sku} | ${bodega}` : sku);
  movs.forEach((m) => { m.key = llave(m.sku, m.bodega); if (!porBodega && bodegas.size > 1) m.saldo = null; });

  // maestro
  const maestro = new Map();
  if (filasMae && filasMae.length) {
    const encMae = Object.keys(filasMae[0]);
    const colMae = detectarColumnas(encMae, cfg.mapeo_maestro || cfg.mapeo, ['sku', 'producto', 'unidad', 'stock_actual', 'costo_unitario', 'lead_time_dias', 'lead_time_desv_dias', 'moq', 'en_transito', 'fecha_llegada_transito', 'proveedor', 'activo', 'vida_util_dias', 'bodega']);
    const utiles = { stock_actual: 'stock actual', costo_unitario: 'costo', lead_time_dias: 'plazo de entrega', moq: 'pedido minimo', en_transito: 'pedidos en transito', proveedor: 'proveedor' };
    const faltan = Object.entries(utiles).filter(([campo]) => !colMae[campo]).map(([, nombre]) => nombre);
    if (colMae.sku && faltan.length) avisos.push(`Columnas del maestro que no se reconocieron (se usan valores por defecto o se omiten): ${faltan.join(', ')}. Columnas recibidas: ${encMae.slice(0, 14).join(', ')}. Si existen con otro nombre, indicalo en el mapeo de la configuracion.`);
    if (!colMae.sku) avisos.push('El maestro de productos no tiene columna de codigo reconocible: se ignora.');
    else {
      for (const fila of filasMae) {
        const sku = String(fila[colMae.sku] ?? '').trim();
        if (!sku) continue;
        const num = (campo) => { const n = colMae[campo] ? parsearNumero(fila[colMae[campo]]) : NaN; return Number.isFinite(n) ? n : null; };
        const activoTxt = colMae.activo ? norm(fila[colMae.activo]) : '';
        const llegada = colMae.fecha_llegada_transito ? parsearFecha(fila[colMae.fecha_llegada_transito], cfg.formato_fecha) : null;
        const bodega = colMae.bodega ? String(fila[colMae.bodega] ?? '').trim() : '';
        maestro.set(llave(sku, bodega), {
          sku, nombre: colMae.producto ? String(fila[colMae.producto] ?? '').trim() : '', unidad: colMae.unidad ? String(fila[colMae.unidad] ?? '').trim() : '',
          stock_actual: num('stock_actual'), costo: num('costo_unitario'), lead_time: num('lead_time_dias'), lead_time_desv: num('lead_time_desv_dias'),
          moq: num('moq'), en_transito: num('en_transito') || 0, llegada_transito: llegada ? llegada.dia : null,
          proveedor: colMae.proveedor ? String(fila[colMae.proveedor] ?? '').trim() : '',
          activo: !['no', 'inactivo', '0', 'false', 'descontinuado', 'baja'].includes(activoTxt),
          vida_util: num('vida_util_dias'),
        });
      }
    }
  } else avisos.push('No se leyo el maestro de productos: no se puede detectar los productos que nunca se movieron ni usar el stock actual, el costo y el plazo de entrega del sistema.');
  const skusMov = new Set(movs.map((m) => m.key));
  calidad.skus_sin_maestro = maestro.size ? [...skusMov].filter((k) => !maestro.has(k)) : [];
  calidad.maestro_sin_movimientos = maestro.size ? [...maestro.keys()].filter((k) => !skusMov.has(k)).length : 0;
  if (calidad.skus_sin_maestro.length) avisos.push(`Productos con movimientos que no estan en el maestro: ${calidad.skus_sin_maestro.length} (${calidad.skus_sin_maestro.slice(0, 4).join(', ')}). Se analizan sin stock actual, plazo ni costo del sistema.`);
  return { movs, maestro, avisos, calidad, porBodega, bodegas: [...bodegas] };
}

// Motor de calculo del agente de inventarios. Todo es codigo determinista: la IA no calcula nada.
// Politica: revision periodica (R,S). Se compra si la posicion proyectada al proximo corte cae bajo el punto de reorden,
// y se pide hasta el nivel objetivo S = D x (L + R) + stock de seguridad. Los parametros salen de 00_motor y se pueden cambiar.
const DEFECTOS = {
  R_dias: 30,
  lead_time_defecto: 15,
  tope_censura: 2,
  z_por_clase: { A: 2.05, B: 1.645, C: 1.28, N: 1.645 },
  sector: 'general',
  cobertura_maxima_sector: { general: 90, alimentos: 45, comercio: 60, manufactura: 120, pesados: 180 },
  dias_sin_movimiento_min: 90,
  meses_ventana: 12,
  alfa_ses: 0.3,
  alfa_croston: 0.2,
  corte_abc: [0.8, 0.95],
  dias_producto_nuevo: 90,
};

const suma = (a) => a.reduce((s, x) => s + x, 0);
const media = (a) => (a.length ? suma(a) / a.length : 0);
const desvMuestral = (a) => { if (a.length < 2) return 0; const m = media(a); return Math.sqrt(suma(a.map((x) => (x - m) ** 2)) / (a.length - 1)); };

// ---------- serie diaria de saldo ----------
// Devuelve el saldo de cierre de cada dia desde el primer movimiento hasta diaFin.
//  'saldo'        : el sistema trae el saldo posterior a cada movimiento
//  'stock_actual' : se reconstruye hacia atras desde el stock actual del maestro
//  'asumido_cero' : no hay ancla; se asume saldo inicial 0 (el quiebre deja de ser confiable)
function construirSerie(movs, stockActual, diaFin) {
  if (!movs.length) return null;
  const dMin = movs[0].dia;
  const n = diaFin - dMin + 1;
  if (n <= 0) return null;
  const delta = new Array(n).fill(0);
  const saldoDia = new Array(n).fill(null);
  let conSaldo = 0;
  for (const m of movs) {
    const i = m.dia - dMin;
    if (i < 0 || i >= n) continue;
    delta[i] += m.efecto;
    if (m.saldo !== null) { saldoDia[i] = m.saldo; conSaldo++; }
  }
  const bal = new Array(n);
  let base;
  let descuadre = null;
  if (conSaldo >= 0.8 * movs.length) {
    base = 'saldo';
    let previo = 0;
    for (let i = 0; i < n; i++) { previo = saldoDia[i] !== null ? saldoDia[i] : previo + delta[i]; bal[i] = previo; }
    if (stockActual !== null && stockActual !== undefined) descuadre = stockActual - bal[n - 1];
  } else {
    let acum = 0;
    for (let i = 0; i < n; i++) { acum += delta[i]; bal[i] = acum; }
    if (stockActual !== null && stockActual !== undefined) { base = 'stock_actual'; const desfase = stockActual - bal[n - 1]; for (let i = 0; i < n; i++) bal[i] += desfase; }
    else base = 'asumido_cero';
  }
  return { dMin, dFin: diaFin, bal, base, descuadre, negativos: bal.filter((x) => x < 0).length };
}

const saldoEn = (serie, dia) => {
  if (!serie || dia < serie.dMin) return null;
  return serie.bal[Math.min(dia, serie.dFin) - serie.dMin];
};

// Detalle de los dias en cero del mes: primer dia, ultimo dia y cuantos episodios seguidos hubo.
function quiebreMes(serie, ym, corte) {
  const desde = Math.max(primerDiaMes(ym), serie.dMin);
  let primero = null;
  let ultimo = null;
  let episodios = 0;
  let enCero = false;
  for (let d = desde; d <= corte; d++) {
    const cero = saldoEn(serie, d) <= 0;
    if (cero) { if (primero === null) primero = d; ultimo = d; if (!enCero) episodios++; }
    enCero = cero;
  }
  return { desde: primero, hasta: ultimo, episodios, sigue: enCero };
}

// ---------- agregados mensuales ----------
function agregarMeses(movs, serie, ymFin, nMeses, diaFin, quiebreConfiable) {
  const iFin = mesIndice(ymFin);
  const dMin = movs.length ? movs[0].dia : null;
  const recs = [];
  const porMes = new Map();
  for (const m of movs) {
    const k = mesIndice(mesDeDia(m.dia));
    if (!porMes.has(k)) porMes.set(k, []);
    porMes.get(k).push(m);
  }
  for (let k = iFin - nMeses + 1; k <= iFin; k++) {
    const ym = mesDeIndice(k);
    const ini = primerDiaMes(ym);
    const fin = ultimoDiaMes(ym);
    const limite = Math.min(fin, diaFin);
    if (dMin === null || limite < dMin) { recs.push({ ym, k, dias_mes: diasDelMes(ym), activos: 0, salidas: 0, devol: 0, demanda_neta: 0, entradas: 0, ajustes_pos: 0, ajustes_neg: 0, dias_con_salida: 0, dias_en_cero: null, cierre: null }); continue; }
    const desde = Math.max(ini, dMin);
    const activos = limite - desde + 1;
    const ms = porMes.get(k) || [];
    const sal = ms.filter((m) => m.tipo === 'salida');
    const salidas = suma(sal.map((m) => m.cantidad));
    const devol = suma(ms.filter((m) => m.tipo === 'devolucion_cliente').map((m) => m.cantidad));
    let diasCero = null;
    if (serie && quiebreConfiable) { diasCero = 0; for (let d = desde; d <= limite; d++) if (saldoEn(serie, d) <= 0) diasCero++; }
    recs.push({
      ym, k, dias_mes: diasDelMes(ym), activos, salidas, devol, demanda_neta: Math.max(0, salidas - devol),
      entradas: suma(ms.filter((m) => m.tipo === 'entrada').map((m) => m.cantidad)),
      ajustes_pos: suma(ms.filter((m) => m.tipo === 'ajuste_pos').map((m) => m.cantidad)), ajustes_neg: suma(ms.filter((m) => m.tipo === 'ajuste_neg').map((m) => m.cantidad)),
      dias_con_salida: new Set(sal.map((m) => m.dia)).size, dias_en_cero: diasCero, cierre: serie ? saldoEn(serie, limite) : null,
    });
  }
  return recs;
}

// Demanda del mes corregida: un mes con quiebre vende menos de lo que se pidio (demanda censurada).
// Se calcula sobre los dias con stock, con un tope; si mas de la mitad de los dias estuvo en cero el mes se trata como dato faltante.
function demandaAjustada(r, P) {
  if (r.activos <= 0) return null;
  let d = r.demanda_neta;
  if (r.activos < r.dias_mes) {
    if (r.activos < 15) return null;
    d = (d * r.dias_mes) / r.activos;
  }
  const dz = r.dias_en_cero;
  if (dz !== null && dz > 0) {
    if (dz > 0.5 * r.activos) return null;
    if (r.demanda_neta > 0) d *= Math.min(P.tope_censura, r.activos / (r.activos - dz));
  }
  return d;
}

// ---------- pronostico ----------
function crostonSBA(v, alfa) {
  let z = null;
  let p = null;
  let desde = 1;
  for (const x of v) {
    if (x > 0) {
      if (z === null) { z = x; p = desde; } else { z += alfa * (x - z); p += alfa * (desde - p); }
      desde = 1;
    } else desde++;
  }
  return z === null ? 0 : (1 - alfa / 2) * (z / p);
}

function suavizadoExponencial(v, alfa) {
  let nivel = media(v.slice(0, Math.min(3, v.length)));
  for (const x of v) nivel = alfa * x + (1 - alfa) * nivel;
  return nivel;
}

// Patron de demanda de Syntetos y Boylan: ADI (intervalo medio entre demandas) y CV2 de los tamanos de demanda.
function pronosticar(valores, P) {
  const n = valores.length;
  const base = { n, metodo: 'sin datos', demanda: 0, sigma: 0, maximo: 0, patron: 'sin demanda', adi: null, cv2: null, confianza: 'BAJA' };
  if (!n) return base;
  const nz = valores.filter((x) => x > 0);
  const adi = nz.length ? n / nz.length : Infinity;
  const cv2 = nz.length >= 2 && media(nz) > 0 ? (desvMuestral(nz) / media(nz)) ** 2 : 0;
  const patron = !nz.length ? 'sin demanda' : adi < 1.32 ? (cv2 < 0.49 ? 'suave' : 'erratica') : (cv2 < 0.49 ? 'intermitente' : 'irregular');
  const out = { ...base, n, adi: Number.isFinite(adi) ? adi : null, cv2, patron, sigma: desvMuestral(valores), maximo: Math.max(...valores) };
  if (n < 3) return { ...out, metodo: 'promedio simple (historial insuficiente)', demanda: media(valores), confianza: 'BAJA' };
  if ((patron === 'intermitente' || patron === 'irregular') && nz.length >= 2) return { ...out, metodo: 'Croston con correccion SBA (demanda intermitente)', demanda: crostonSBA(valores, P.alfa_croston), confianza: 'MEDIA' };
  if (n >= 6) return { ...out, metodo: 'suavizado exponencial simple', demanda: suavizadoExponencial(valores, P.alfa_ses), confianza: patron === 'suave' ? 'ALTA' : 'MEDIA' };
  return { ...out, metodo: 'promedio movil simple (pocos meses)', demanda: media(valores), confianza: 'MEDIA' };
}

// ---------- politica de reposicion ----------
// Stock de seguridad para un periodo de proteccion de `dias` dias. Con 6 o mas meses se usa la desviacion estandar
// (y la del plazo de entrega si se conoce); con menos, el metodo simplificado (demanda maxima menos promedio).
function stockSeguridad(d, dias) {
  if (d.n >= 6) {
    const varDemanda = (dias / 30) * d.sigma ** 2;
    const varPlazo = d.sigmaL ? ((d.demandaMes * d.sigmaL) / 30) ** 2 : 0;
    return d.Z * Math.sqrt(varDemanda + varPlazo);
  }
  return Math.max(0, d.maximo - d.demandaMes) * (dias / 30);
}

function politica(d, P) {
  const Ddia = d.demandaMes / 30;
  const L = d.L;
  const R = d.R;
  const ssL = stockSeguridad(d, L);
  const ssLR = stockSeguridad(d, L + R);
  const rop = Ddia * L + ssL;
  const S = Ddia * (L + R) + ssLR;
  const posicion = d.stock + d.transito;
  const proyectada = posicion - Ddia * R;
  const comprar = Ddia > 0 && proyectada <= rop;
  let cantidad = 0;
  if (comprar) {
    cantidad = Math.max(0, S - posicion);
    if (d.moq && d.moq > 1) cantidad = Math.ceil(cantidad / d.moq) * d.moq;
    cantidad = Math.ceil(cantidad);
  }
  const cobertura = Ddia > 0 ? d.stock / Ddia : Infinity;
  return { Ddia, rop, S, ss: ssLR, posicion, proyectada, comprar, cantidad, cobertura, urgente: Ddia > 0 && (d.stock <= 0 || cobertura <= L) };
}

// ---------- calculo completo del mes ----------
function calcularInventario(datos, cfg, parametros) {
  const P = { ...DEFECTOS, ...(parametros || {}), z_por_clase: { ...DEFECTOS.z_por_clase, ...((parametros || {}).z_por_clase || {}) } };
  const ym = cfg.mes;
  const avisos = [...datos.avisos];
  const porKey = new Map();
  for (const m of datos.movs) { if (!porKey.has(m.key)) porKey.set(m.key, []); porKey.get(m.key).push(m); }
  for (const lista of porKey.values()) lista.sort((a, b) => a.dia - b.dia || a.idx - b.idx);
  const diaFin = datos.movs.length ? Math.max(...datos.movs.map((m) => m.dia)) : 0;
  const finMes = ultimoDiaMes(ym);
  const corte = Math.min(finMes, diaFin);
  if (diaFin < finMes) avisos.push(`Los movimientos llegan hasta ${isoDe(diaFin)}, antes del fin de ${ym}: el mes esta incompleto y el informe se calcula al ${isoDe(corte)}.`);
  if (diaFin > finMes + 40) avisos.push(`Hay movimientos hasta ${isoDe(diaFin)}, posteriores al mes pedido (${ym}). Se usan solo para reconstruir el saldo; el analisis es al ${isoDe(finMes)}.`);
  const claves = new Set([...porKey.keys(), ...datos.maestro.keys()]);
  const resultados = [];
  const calidad = { ...datos.calidad, descuadres: [], saldo_negativo: [], sin_ancla: [], plazo_supuesto: 0, sin_costo: 0 };
  const nVentana = P.meses_ventana + 2;

  for (const key of claves) {
    const movs = porKey.get(key) || [];
    const mae = datos.maestro.get(key) || null;
    const sku = mae ? mae.sku : (movs[0] ? movs[0].sku : key);
    const nombre = (mae && mae.nombre) || (movs.find((m) => m.producto) || {}).producto || '';
    if (mae && !mae.activo) { resultados.push({ key, sku, nombre, accion: 'INACTIVO', motivo: 'Marcado como inactivo en el maestro.', stock: mae.stock_actual || 0, costo: mae.costo || 0, valor_stock: (mae.stock_actual || 0) * (mae.costo || 0), clase: '-', cantidad: 0, valor_compra: 0, proveedor: mae.proveedor, salidas_mes: 0, entradas_mes: 0, dias_en_cero: 0, confianza: '-' }); continue; }
    const mensual = datos.calidad.granularidad_mensual;
    const serie = mensual ? null : construirSerie(movs, mae ? mae.stock_actual : null, diaFin);
    const quiebreConfiable = !!serie && serie.base !== 'asumido_cero';
    if (serie && serie.base === 'asumido_cero') calidad.sin_ancla.push(sku);
    if (serie && serie.descuadre !== null && Math.abs(serie.descuadre) > 0.5) calidad.descuadres.push({ sku, diferencia: serie.descuadre });
    if (serie && serie.negativos > 0) calidad.saldo_negativo.push(sku);

    const meses = agregarMeses(movs, serie, ym, nVentana, diaFin, quiebreConfiable);
    const mesActual = meses[meses.length - 1];
    const previos3 = meses.slice(-4, -1).filter((r) => r.activos >= r.dias_mes);
    const promedio3 = previos3.length ? media(previos3.map((r) => r.demanda_neta)) : null;
    const quiebre = serie && quiebreConfiable && mesActual.dias_en_cero > 0 ? quiebreMes(serie, ym, corte) : null;
    const alta = movs.length ? movs[0].dia : null;
    const stockCorte = serie ? saldoEn(serie, corte) : (mae && mae.stock_actual !== null ? mae.stock_actual : 0);
    const stock = Math.max(0, stockCorte === null ? (mae ? (mae.stock_actual || 0) : 0) : stockCorte);
    const ultimoCosto = [...movs].reverse().find((m) => m.costo !== null);
    const costo = (mae && mae.costo) || (ultimoCosto ? ultimoCosto.costo : 0);
    if (!costo) calidad.sin_costo++;
    const L = mae && mae.lead_time ? mae.lead_time : P.lead_time_defecto;
    if (!(mae && mae.lead_time)) calidad.plazo_supuesto++;
    const sal = movs.filter((m) => m.tipo === 'salida' && m.dia <= corte);
    const diasSalida = [...new Set(sal.map((m) => m.dia))].sort((a, b) => a - b);
    const ultimaSalida = diasSalida.length ? diasSalida[diasSalida.length - 1] : null;
    const diasSinSalida = ultimaSalida !== null ? corte - ultimaSalida : null;
    const gaps = diasSalida.slice(1).map((d, i) => d - diasSalida[i]);
    const intervaloMedio = diasSalida.length >= 4 ? media(gaps) : null;
    const edadDias = alta !== null ? corte - alta : null;
    const nuevo = alta !== null && corte - alta < P.dias_producto_nuevo;

    const valores = meses.map((r) => demandaAjustada(r, P)).filter((x) => x !== null);
    const f = pronosticar(valores, P);
    const ventana12 = meses.slice(-P.meses_ventana);
    const cons12 = suma(ventana12.map((r) => r.demanda_neta));

    resultados.push({
      key, sku, nombre, unidad: mae ? mae.unidad : '', proveedor: mae ? mae.proveedor : '', costo, stock, transito: mae ? mae.en_transito : 0, moq: mae ? mae.moq : null, L, sigmaL: mae ? mae.lead_time_desv : null,
      plazo_supuesto: !(mae && mae.lead_time), vida_util: mae ? mae.vida_util : null, llegada_transito: mae ? mae.llegada_transito : null,
      sin_maestro: !mae, alta, nuevo, edad_dias: edadDias, serie_base: serie ? serie.base : (mensual ? 'mensual' : 'sin movimientos'), quiebre_confiable: quiebreConfiable,
      salidas_mes: mesActual.salidas, devol_mes: mesActual.devol, demanda_neta_mes: mesActual.demanda_neta, entradas_mes: mesActual.entradas, ajustes_pos_mes: mesActual.ajustes_pos, ajustes_neg_mes: mesActual.ajustes_neg,
      promedio_3m: promedio3, quiebre,
      dias_con_salida_mes: mesActual.dias_con_salida, dias_en_cero: mesActual.dias_en_cero,
      stock_inicial: serie ? saldoEn(serie, primerDiaMes(ym) - 1) : null, stock_cierre: serie ? saldoEn(serie, corte) : null,
      ultima_salida: ultimaSalida, dias_sin_salida: diasSinSalida, intervalo_medio: intervaloMedio, salio_alguna_vez: diasSalida.length > 0,
      meses, valores, pron: f, consumo12: cons12, valor_consumo12: cons12 * costo, valor_stock: stock * costo,
      mismo_mes_anio_anterior: (meses.find((r) => r.k === mesIndice(ym) - 12) || {}).demanda_neta || 0, nuevo_poco_historial: nuevo && f.n < 3,
    });
  }

  // ---------- clasificacion ABC por valor de consumo de los ultimos 12 meses (el SKU que cruza el umbral queda en la clase superior) ----------
  const activos = resultados.filter((r) => r.accion !== 'INACTIVO');
  const conClase = activos.filter((r) => !r.nuevo).sort((a, b) => b.valor_consumo12 - a.valor_consumo12);
  const total = suma(conClase.map((r) => r.valor_consumo12));
  let acum = 0;
  for (const r of conClase) {
    const antes = total > 0 ? acum / total : 1;
    r.clase = r.valor_consumo12 <= 0 ? 'C' : antes < P.corte_abc[0] ? 'A' : antes < P.corte_abc[1] ? 'B' : 'C';
    acum += r.valor_consumo12;
  }
  activos.filter((r) => r.nuevo).forEach((r) => { r.clase = 'N'; });
  if (conClase.length < 10) avisos.push('Hay pocos productos (menos de 10): la clasificacion ABC es orientativa.');

  // ---------- decision por producto ----------
  const sector = P.sector in P.cobertura_maxima_sector ? P.sector : 'general';
  for (const r of activos) {
    const fp = r.pron;
    r.xyz = fp.n >= 6 && fp.demanda > 0 ? (() => { const cv = fp.sigma / media(r.valores); return cv < 0.5 ? 'X' : cv <= 1 ? 'Y' : 'Z'; })() : null;
    const Z = P.z_por_clase[r.clase] || P.z_por_clase.B;
    r.nivel_servicio = { A: '98%', B: '95%', C: '90%', N: '95%' }[r.clase] || '95%';
    const pol = politica({ demandaMes: fp.demanda, sigma: fp.sigma, maximo: fp.maximo, n: fp.n, Z, L: r.L, sigmaL: r.sigmaL, R: P.R_dias, stock: r.stock, transito: r.transito, moq: r.moq }, P);
    Object.assign(r, { Ddia: pol.Ddia, rop: pol.rop, S: pol.S, ss: pol.ss, posicion: pol.posicion, proyectada: pol.proyectada, cobertura: pol.cobertura });
    r.confianza = fp.confianza;
    if (r.sin_maestro && r.serie_base === 'asumido_cero') r.confianza = 'BAJA';
    const umbralCob = Math.max(2 * (r.L + P.R_dias), P.cobertura_maxima_sector[sector]);
    r.umbral_cobertura = umbralCob;
    const umbralMuerto = Math.max(P.dias_sin_movimiento_min, r.intervalo_medio ? Math.min(365, 3 * r.intervalo_medio) : 0);
    r.umbral_sin_movimiento = umbralMuerto;
    const edad = r.dias_sin_salida;
    r.tramo_edad = edad === null ? null : edad >= 365 ? '365 o mas' : edad >= 180 ? '180 a 364' : '90 a 179';
    r.transito_vencido = r.llegada_transito !== null && r.llegada_transito < corte && r.transito > 0;
    r.exceso_unidades = Math.max(0, pol.posicion - pol.S);
    r.exceso_valor = r.exceso_unidades * r.costo;
    r.ventas_perdidas = r.dias_en_cero > 0 ? Math.round(pol.Ddia * r.dias_en_cero) : 0;
    const quiebreActual = r.stock <= 0 && (pol.Ddia > 0 || r.consumo12 > 0);
    const nunca = r.stock > 0 && !r.salio_alguna_vez;
    const sinMov = r.stock > 0 && r.salio_alguna_vez && edad !== null && edad >= umbralMuerto && !r.nuevo;
    const sobre = pol.Ddia > 0 && pol.cobertura > umbralCob && r.stock > 0;
    const motivoMeta = `Politica de revision mensual: nivel de servicio ${r.nivel_servicio}, plazo ${r.L} dias${r.plazo_supuesto ? ' (supuesto)' : ''}.`;
    if (r.serie_base === 'asumido_cero' && r.sin_maestro) {
      r.accion = 'REVISAR DATOS';
      r.cantidad = 0;
      r.confianza = 'BAJA';
      r.motivo = 'No hay stock actual ni saldo por movimiento para este producto: el stock es desconocido y no se puede recomendar una compra. Agregalo al maestro de productos.';
    } else if (quiebreActual) {
      r.accion = 'COMPRAR URGENTE';
      r.cantidad = Math.max(pol.cantidad, Math.ceil(Math.max(0, pol.S - pol.posicion)));
      if (r.moq && r.moq > 1) r.cantidad = Math.ceil(r.cantidad / r.moq) * r.moq;
      r.motivo = `Sin stock al cierre${r.transito > 0 ? ` (hay ${r.transito} en transito${r.transito_vencido ? ', con fecha de llegada vencida' : ''})` : ''}. Riesgo que mitiga: quiebre. ${motivoMeta}`;
      if (r.cantidad <= 0) { r.accion = 'SIN STOCK, PEDIDO EN CAMINO'; r.cantidad = 0; r.motivo = `Sin stock al cierre, pero lo que viene en transito (${r.transito}) cubre el nivel objetivo.${r.transito_vencido ? ' La fecha de llegada ya vencio: confirma con el proveedor.' : ''}`; }
    } else if (sinMov) {
      r.accion = 'SIN MOVIMIENTO';
      r.cantidad = 0;
      r.motivo = `Ultima salida hace ${edad} dias (umbral ${Math.round(umbralMuerto)}). Riesgo: capital inmovilizado y obsolescencia.${r.mismo_mes_anio_anterior > 0 ? ' Vendio en el mismo mes del ano pasado: puede ser estacional.' : ''}`;
    } else if (pol.comprar) {
      r.accion = pol.urgente ? 'COMPRAR URGENTE' : 'COMPRAR';
      r.cantidad = pol.cantidad;
      r.motivo = `Posicion proyectada al proximo corte (${Math.round(pol.proyectada)}) por debajo del punto de reorden (${Math.round(pol.rop)}); la cobertura es de ${Math.round(pol.cobertura)} dias${pol.urgente ? ', menos que el plazo de entrega' : ''}. Riesgo que mitiga: quiebre. ${motivoMeta}`;
    } else if (nunca) {
      r.accion = 'NUNCA SE MOVIO';
      r.cantidad = 0;
      r.motivo = `Tiene ${r.stock} en stock y ninguna salida en todo el historial leido. Riesgo: capital inmovilizado.`;
    } else if (sobre) {
      r.accion = 'SOBRESTOCK';
      r.cantidad = 0;
      r.motivo = `Cobertura de ${Math.round(pol.cobertura)} dias, por encima de ${Math.round(umbralCob)}. Excedente de ${Math.round(r.exceso_unidades)} unidades sobre el nivel objetivo. Riesgo: capital inmovilizado.`;
    } else if (pol.Ddia === 0 && r.stock <= 0) {
      r.accion = 'SIN DEMANDA';
      r.cantidad = 0;
      r.motivo = 'Sin stock y sin demanda en la ventana analizada.';
    } else {
      r.accion = 'NO COMPRAR';
      r.cantidad = 0;
      r.motivo = `Stock suficiente: cobertura de ${pol.cobertura === Infinity ? 'sin demanda' : Math.round(pol.cobertura) + ' dias'}, posicion proyectada ${Math.round(pol.proyectada)} sobre el punto de reorden ${Math.round(pol.rop)}.`;
    }
    r.valor_compra = r.cantidad * r.costo;
    if (r.clase === 'A' && (r.xyz === 'Z' || fp.patron === 'irregular') && (r.accion === 'COMPRAR' || r.accion === 'COMPRAR URGENTE')) r.revisar_manual = 'Producto de alto valor con demanda errática: confirma la cantidad con el área comercial antes de pedir.';
  }

  return { resultados: activos.concat(resultados.filter((r) => r.accion === 'INACTIVO')), P, ym, corte, avisos, calidad, diaFin };
}

// ---------- exactitud del pronostico (backtest con datos hasta el mes anterior) ----------
function backtest(resultados, P, mesesAtras) {
  const out = { n: 0, real: 0, abs: 0, sesgo: 0, abs_ingenuo: 0, por_clase: {} };
  for (const r of resultados) {
    if (!r.meses || r.accion === 'INACTIVO') continue;
    for (let j = 0; j < mesesAtras; j++) {
      const idx = r.meses.length - 1 - j;
      if (idx < 1) continue;
      const mesReal = r.meses[idx];
      const previos = r.meses.slice(0, idx).map((x) => demandaAjustada(x, P)).filter((x) => x !== null);
      if (previos.length < 3 || mesReal.activos < mesReal.dias_mes) continue;
      const pron = pronosticar(previos, P).demanda;
      const real = mesReal.demanda_neta;
      const ingenuo = r.meses[idx - 1].demanda_neta;
      out.n++;
      out.real += real;
      out.abs += Math.abs(real - pron);
      out.sesgo += pron - real;
      out.abs_ingenuo += Math.abs(real - ingenuo);
      const c = r.clase || '-';
      out.por_clase[c] = out.por_clase[c] || { real: 0, abs: 0 };
      out.por_clase[c].real += real;
      out.por_clase[c].abs += Math.abs(real - pron);
    }
  }
  return {
    observaciones: out.n,
    wape: out.real > 0 ? out.abs / out.real : null,
    sesgo: out.real > 0 ? out.sesgo / out.real : null,
    wape_ingenuo: out.real > 0 ? out.abs_ingenuo / out.real : null,
    wape_por_clase: Object.fromEntries(Object.entries(out.por_clase).map(([c, v]) => [c, v.real > 0 ? v.abs / v.real : null])),
  };
}

// ---------- indicadores del mes ----------
function indicadores(res, P) {
  const rs = res.resultados.filter((r) => r.accion !== 'INACTIVO');
  const valorInv = suma(rs.map((r) => r.valor_stock));
  const conQuiebreConfiable = rs.filter((r) => r.quiebre_confiable);
  const activosVentas = rs.filter((r) => r.consumo12 > 0);
  const enQuiebre = activosVentas.filter((r) => r.quiebre_confiable && r.dias_en_cero > 0);
  const claseA = activosVentas.filter((r) => r.clase === 'A' && r.quiebre_confiable);
  const pesoTotal = suma(conQuiebreConfiable.filter((r) => r.consumo12 > 0).map((r) => r.valor_consumo12));
  const disponibilidad = pesoTotal > 0 ? suma(conQuiebreConfiable.filter((r) => r.consumo12 > 0).map((r) => r.valor_consumo12 * (1 - Math.min(1, (r.dias_en_cero || 0) / Math.max(1, r.meses[r.meses.length - 1].activos)))) ) / pesoTotal : null;
  const cogs12 = suma(rs.map((r) => r.valor_consumo12));
  const promedios = rs.filter((r) => r.serie_base !== 'asumido_cero' && r.meses.some((m) => m.cierre !== null)).map((r) => media(r.meses.filter((m) => m.cierre !== null).map((m) => Math.max(0, m.cierre) * r.costo)));
  const invPromedio = suma(promedios);
  const rotacion = invPromedio > 0 ? cogs12 / invPromedio : null;
  const muertos = rs.filter((r) => r.accion === 'SIN MOVIMIENTO' || r.accion === 'NUNCA SE MOVIO');
  const tramos = { '90 a 179': 0, '180 a 364': 0, '365 o mas': 0, 'sin ventas en el historial': 0 };
  muertos.forEach((r) => { tramos[r.accion === 'NUNCA SE MOVIO' ? 'sin ventas en el historial' : r.tramo_edad] += r.valor_stock; });
  const compras = rs.filter((r) => r.cantidad > 0);
  const porProveedor = {};
  const porClase = {};
  compras.forEach((r) => { const p = r.proveedor || 'Sin proveedor'; porProveedor[p] = (porProveedor[p] || 0) + r.valor_compra; porClase[r.clase] = (porClase[r.clase] || 0) + r.valor_compra; });
  const aj = suma(rs.map((r) => (r.ajustes_pos_mes + r.ajustes_neg_mes) * r.costo));
  const sal = suma(rs.map((r) => r.salidas_mes * r.costo));
  const cuenta = {};
  rs.forEach((r) => { cuenta[r.accion] = (cuenta[r.accion] || 0) + 1; });
  return {
    productos: rs.length, productos_con_ventas_12m: activosVentas.length, cuenta_acciones: cuenta, valor_inventario: valorInv,
    rotacion_anual: rotacion, dias_inventario: rotacion ? 365 / rotacion : null, tasa_quiebre: activosVentas.length && conQuiebreConfiable.length ? enQuiebre.length / activosVentas.filter((r) => r.quiebre_confiable).length : null,
    productos_en_quiebre: enQuiebre.length, quiebre_clase_a: claseA.length ? claseA.filter((r) => r.dias_en_cero > 0).length : 0, productos_clase_a: claseA.length,
    disponibilidad_ponderada: disponibilidad, valor_muerto: suma(muertos.map((r) => r.valor_stock)), pct_muerto: valorInv > 0 ? suma(muertos.map((r) => r.valor_stock)) / valorInv : null, tramos_muerto: tramos,
    capital_exceso: suma(rs.filter((r) => r.accion === 'SOBRESTOCK').map((r) => r.exceso_valor)), compra_total: suma(compras.map((r) => r.valor_compra)), compra_por_proveedor: porProveedor, compra_por_clase: porClase,
    ajustes_valor: aj, ajustes_pct_salidas: sal > 0 ? aj / sal : null, ventas_perdidas_valor: suma(rs.map((r) => r.ventas_perdidas * r.costo)),
    pronostico: backtest(rs, res.P, 3),
  };
}

// Generador del informe de inventarios: Markdown, HTML, CSV para Excel y respuesta corta del chat.
// Son funciones puras sobre el resultado del motor; los datos que pasan entre nodos de n8n son JSON, asi que
// Infinity llega como null (cobertura null = sin demanda).
const PROMPT_COMENTARIO = `Eres un ingeniero de inventarios senior que escribe el comentario de un informe mensual para el area de compras. Recibes un JSON ya calculado por codigo: conteos por accion, indicadores y las listas mas importantes.

Reglas estrictas:
- Usa SOLO las cifras y nombres del JSON. No inventes productos, cantidades, valores ni causas. No calcules ni redondees: si citas una cifra, copiala tal cual.
- No cambies ninguna recomendacion ni cantidad: el sistema ya decidio. Tu trabajo es ordenar prioridades y explicar el panorama.
- No nombres ninguna moneda (ni pesos ni dolares): usa solo las cifras. No califiques volumenes como grandes o pequenos ni inventes causas de los quiebres.
- Escribe en espanol, en maximo 150 palabras, en prosa breve (sin tablas ni listas largas), con una sola seccion titulada "## Comentario del analista".
- Cubre: que atender primero y por que, el riesgo principal (quiebres o capital inmovilizado) y una advertencia sobre la confiabilidad de los datos si el JSON la trae.
- No uses guiones largos (el caracter de raya). Usa comas, puntos, dos puntos o parentesis.`;

const MESES_NOMBRE = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const mesTexto = (ym) => `${MESES_NOMBRE[Number(ym.slice(5, 7)) - 1]} ${ym.slice(0, 4)}`;

function armarInforme(entrada) {
  const { res, ind, cfg, comentario, uso, tiempos } = entrada;
  const moneda = cfg.moneda || '$';
  const miles = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const num = (x) => (x === null || x === undefined || Number.isNaN(x) ? '-' : Math.abs(x) >= 100 || Number.isInteger(x) ? miles(x) : String(Math.round(x * 100) / 100).replace('.', ','));
  const dinero = (x) => (x === null || x === undefined ? '-' : `${moneda} ${miles(x)}`);
  const pct = (x) => (x === null || x === undefined ? '-' : `${(x * 100).toFixed(1).replace('.', ',')}%`);
  const fecha = (d) => (d === null || d === undefined ? '-' : isoDe(d));
  const cob = (r) => (r.cobertura === null || r.cobertura === undefined || r.cobertura === Infinity ? 'sin demanda' : miles(r.cobertura));
  const nombre = (r) => celda(r.nombre ? `${r.nombre} (${r.sku})` : r.sku);
  const rs = res.resultados;
  const por = (accion) => rs.filter((r) => r.accion === accion);
  const urgentes = rs.filter((r) => r.accion === 'COMPRAR URGENTE').sort((a, b) => ((a.cobertura ?? 1e9) - a.L) - ((b.cobertura ?? 1e9) - b.L));
  const normales = rs.filter((r) => r.accion === 'COMPRAR').sort((a, b) => (a.cobertura ?? 1e9) - (b.cobertura ?? 1e9));
  const enCamino = por('SIN STOCK, PEDIDO EN CAMINO');
  const quiebres = rs.filter((r) => r.quiebre_confiable && r.dias_en_cero > 0).sort((a, b) => b.dias_en_cero - a.dias_en_cero);
  const sinMov = por('SIN MOVIMIENTO').sort((a, b) => b.valor_stock - a.valor_stock);
  const nunca = por('NUNCA SE MOVIO').sort((a, b) => b.valor_stock - a.valor_stock);
  const sobre = por('SOBRESTOCK').sort((a, b) => b.exceso_valor - a.exceso_valor);
  const suficientes = rs.filter((r) => r.accion === 'NO COMPRAR' || r.accion === 'SIN DEMANDA').sort((a, b) => (a.cobertura ?? 1e9) - (b.cobertura ?? 1e9));
  const revisar = por('REVISAR DATOS');
  const inactivos = por('INACTIVO');
  const movidos = rs.filter((r) => r.accion !== 'INACTIVO' && (r.salidas_mes > 0 || r.entradas_mes > 0)).sort((a, b) => b.salidas_mes * b.costo - a.salidas_mes * a.costo);
  const aSurtir = [...urgentes, ...normales];
  const nota = (r) => [
    r.transito > 0 ? `en transito: ${num(r.transito)}${r.transito_vencido ? ' (llegada vencida)' : ''}` : '',
    r.plazo_supuesto ? 'plazo supuesto' : '',
    r.moq > 1 ? `multiplo ${num(r.moq)}` : '',
    r.confianza === 'BAJA' ? 'confianza baja' : '',
    r.revisar_manual ? 'confirmar con comercial' : '',
  ].filter(Boolean).join('; ');
  const L = [];
  const tabla = (encabezados, filas) => { L.push(`| ${encabezados.join(' | ')} |`); L.push(`|${encabezados.map(() => '---').join('|')}|`); filas.forEach((f) => L.push(`| ${f.map((c) => celda(c)).join(' | ')} |`)); L.push(''); };
  const LIMITE = 40;

  L.push(`# Informe de inventario: ${mesTexto(res.ym)}`);
  L.push('');
  L.push(`Corte al ${isoDe(res.corte)} | ${ind.productos} productos analizados | Fuente: ${cfg.fuente} | Politica: revision mensual (R = ${res.P.R_dias} dias), nivel de servicio 98% / 95% / 90% para clase A / B / C`);
  L.push('');

  // ---------- resumen ----------
  L.push('## Resumen del mes');
  L.push(`- **Productos analizados:** ${ind.productos} (${ind.productos_con_ventas_12m} con ventas en los ultimos 12 meses).`);
  L.push(`- **Que surtir:** ${aSurtir.length} producto${aSurtir.length === 1 ? '' : 's'}, ${urgentes.length} urgente${urgentes.length === 1 ? '' : 's'}. Compra sugerida: **${dinero(ind.compra_total)}** (clase A ${dinero(ind.compra_por_clase.A || 0)}, B ${dinero(ind.compra_por_clase.B || 0)}, C ${dinero(ind.compra_por_clase.C || 0)}${ind.compra_por_clase.N ? `, nuevos ${dinero(ind.compra_por_clase.N)}` : ''}).${enCamino.length ? ` ${enCamino.length} sin stock con el pedido ya en camino.` : ''}`);
  L.push(`- **Se quedaron en cero este mes:** ${quiebres.length} producto${quiebres.length === 1 ? '' : 's'}${quiebres.length ? ` (${quiebres.filter((r) => r.quiebre && r.quiebre.sigue).length} siguen en cero al corte)` : ''}.${ind.ventas_perdidas_valor > 0 ? ` Ventas perdidas estimadas: ${dinero(ind.ventas_perdidas_valor)} (estimacion).` : ''}`);
  L.push(`- **Sin movimiento:** ${sinMov.length}; **nunca se movieron:** ${nunca.length}. Capital inmovilizado: **${dinero(ind.valor_muerto)}** (${pct(ind.pct_muerto)} del inventario).`);
  L.push(`- **Sobrestock:** ${sobre.length} producto${sobre.length === 1 ? '' : 's'}, capital en exceso ${dinero(ind.capital_exceso)}.`);
  L.push(`- **Inventario:** ${dinero(ind.valor_inventario)}. Rotacion anual ${ind.rotacion_anual ? num(Math.round(ind.rotacion_anual * 10) / 10) : '-'} veces (${ind.dias_inventario ? miles(ind.dias_inventario) : '-'} dias de inventario).`);
  if (revisar.length) L.push(`- **Revisar datos:** ${revisar.length} producto${revisar.length === 1 ? '' : 's'} sin stock conocido, no se recomienda compra para ellos.`);
  L.push('');
  if (comentario) { L.push(comentario); L.push(''); }

  // ---------- que surtir ----------
  L.push('## Que surtir');
  if (!aSurtir.length) L.push('Ningun producto necesita compra segun la politica de reposicion.\n');
  const filaSurtir = (r, i) => [i + 1, nombre(r), `${r.clase}${r.xyz ? '/' + r.xyz : ''}`, num(r.stock), num(r.salidas_mes), cob(r), num(r.L), `**${num(r.cantidad)}** ${r.unidad || ''}`, dinero(r.valor_compra), r.proveedor || '-', nota(r)];
  const encSurtir = ['#', 'Producto', 'Clase', 'Stock', 'Salidas del mes', 'Cobertura (dias)', 'Plazo (dias)', 'Cantidad sugerida', 'Costo estimado', 'Proveedor', 'Notas'];
  if (urgentes.length) {
    L.push('### Urgente: se quedarian sin stock antes de que llegue un pedido hecho hoy');
    tabla(encSurtir, urgentes.slice(0, LIMITE).map(filaSurtir));
    if (urgentes.length > LIMITE) L.push(`Se muestran ${LIMITE} de ${urgentes.length}; la lista completa esta en el archivo de pedido sugerido.\n`);
  }
  if (normales.length) {
    L.push('### Para el proximo ciclo: no alcanzaria hasta el siguiente corte');
    tabla(encSurtir, normales.slice(0, LIMITE).map(filaSurtir));
    if (normales.length > LIMITE) L.push(`Se muestran ${LIMITE} de ${normales.length}; la lista completa esta en el archivo de pedido sugerido.\n`);
  }
  if (enCamino.length) { L.push('### Sin stock, con el pedido en camino'); tabla(['Producto', 'En transito', 'Notas'], enCamino.map((r) => [nombre(r), num(r.transito), r.transito_vencido ? 'la fecha de llegada ya vencio: confirmar con el proveedor' : ''])); }
  if (Object.keys(ind.compra_por_proveedor).length) {
    L.push('### Compra sugerida por proveedor');
    tabla(['Proveedor', 'Costo estimado'], Object.entries(ind.compra_por_proveedor).sort((a, b) => b[1] - a[1]).map(([p, v]) => [p, dinero(v)]));
  }
  const manual = aSurtir.filter((r) => r.revisar_manual);
  if (manual.length) L.push(`> Confirmar con el area comercial antes de pedir (producto de alto valor con demanda erratica): ${manual.map((r) => r.sku).join(', ')}.\n`);

  // ---------- quiebres ----------
  L.push('## Se quedaron en cero este mes');
  if (!quiebres.length) L.push('Ningun producto con datos confiables llego a cero durante el mes.\n');
  else tabla(['Producto', 'Dias en cero', 'Desde', 'Hasta', 'Estado', 'Stock al corte', 'Ventas perdidas (estimadas)', 'Accion'], quiebres.map((r) => [nombre(r), r.dias_en_cero, fecha(r.quiebre && r.quiebre.desde), fecha(r.quiebre && r.quiebre.hasta), r.quiebre && r.quiebre.sigue ? 'sigue en cero' : `repuesto${r.quiebre && r.quiebre.episodios > 1 ? ` (${r.quiebre.episodios} episodios)` : ''}`, num(r.stock), r.ventas_perdidas ? `${num(r.ventas_perdidas)} unid. (${dinero(r.ventas_perdidas * r.costo)})` : '-', r.accion]));
  const sinSerie = rs.filter((r) => r.accion !== 'INACTIVO' && !r.quiebre_confiable && r.salio_alguna_vez).length;
  if (sinSerie) L.push(`> Productos sin saldo ni stock actual confiables (no se puede decir si llegaron a cero): ${sinSerie}.\n`);

  // ---------- que se movio ----------
  L.push('## Que tanto se movio');
  if (!movidos.length) L.push('No hubo movimientos en el mes.\n');
  else {
    tabla(['Producto', 'Clase', 'Salio en el mes', 'Cambio vs ultimos 3 meses', 'Dias con salida', 'Entro en el mes', 'Stock al inicio', 'Stock al cierre', 'Patron de demanda'], movidos.slice(0, LIMITE).map((r) => [nombre(r), r.clase, `${num(r.salidas_mes)}${r.devol_mes ? ` (menos ${num(r.devol_mes)} devueltas)` : ''}`, r.promedio_3m && r.promedio_3m >= 5 ? `${r.demanda_neta_mes / r.promedio_3m - 1 >= 0 ? '+' : ''}${pct(r.demanda_neta_mes / r.promedio_3m - 1)}` : '-', r.dias_con_salida_mes, num(r.entradas_mes), r.quiebre_confiable ? num(r.stock_inicial) : '-', r.quiebre_confiable ? num(r.stock_cierre) : '-', r.pron.patron]));
    if (movidos.length > LIMITE) L.push(`Se muestran ${LIMITE} de ${movidos.length}, ordenados por valor de lo que salio.\n`);
  }

  // ---------- sin movimiento ----------
  L.push('## Sin movimiento y nunca se movieron');
  if (!sinMov.length && !nunca.length) L.push('Ningun producto con stock lleva sin salidas mas tiempo del esperado.\n');
  if (sinMov.length) {
    L.push('### Con stock y sin salidas por mas tiempo del esperado');
    tabla(['Producto', 'Stock', 'Valor', 'Ultima salida', 'Dias sin salida', 'Umbral (dias)', 'Notas'], sinMov.map((r) => [nombre(r), num(r.stock), dinero(r.valor_stock), fecha(r.ultima_salida), r.dias_sin_salida, num(r.umbral_sin_movimiento), r.mismo_mes_anio_anterior > 0 ? 'vendio en este mes el ano pasado: revisar si es estacional antes de liquidar' : 'candidato a liquidar, devolver o dar de baja']));
  }
  if (nunca.length) {
    L.push('### Nunca se movieron (sin ninguna salida en el historial leido)');
    tabla(['Producto', 'Stock', 'Valor', 'Notas'], nunca.map((r) => [nombre(r), num(r.stock), dinero(r.valor_stock), r.sin_maestro ? 'sin maestro' : 'revisar si sigue vigente en el catalogo']));
  }
  if (ind.valor_muerto > 0) {
    L.push('Capital inmovilizado por antiguedad de la ultima salida:');
    L.push('');
