    C.push('');
  }
  if (quiebres.length) C.push(`**Se quedaron en cero:** ${quiebres.slice(0, 6).map((r) => `${r.sku} (${r.dias_en_cero} dias${r.quiebre && r.quiebre.sigue ? ', sigue' : ''})`).join(', ')}${quiebres.length > 6 ? ` y ${quiebres.length - 6} mas` : ''}.`);
  if (nunca.length || sinMov.length) C.push(`**Sin rotacion:** ${[...nunca.map((r) => `${r.sku} (nunca)`), ...sinMov.map((r) => `${r.sku} (${r.dias_sin_salida} dias)`)].slice(0, 8).join(', ')}.`);
  if (comentario) { C.push(''); C.push(comentario.replace(/^##[^\n]*\n/, '').trim()); }
  if (res.avisos.length) { C.push(''); res.avisos.slice(0, 3).forEach((a) => C.push(`- Ojo: ${a}`)); }
  const chat = sinGuiones(C.join('\n')).replace(/\n{3,}/g, '\n\n');
  return { md, html, csvPedido, csvDetalle, chat, resumen: { surtir: aSurtir.length, urgentes: urgentes.length, quiebres: quiebres.length, sin_movimiento: sinMov.length, nunca: nunca.length, sobrestock: sobre.length } };
}

function tablaChat(C, enc, filas) {
  C.push(`| ${enc.join(' | ')} |`);
  C.push(`|${enc.map(() => '---').join('|')}|`);
  filas.forEach((f) => C.push(`| ${f.map((c) => celda(c)).join(' | ')} |`));
}

// Quita del comentario de la IA las frases con cifras que no estan en los datos que se le entregaron.
function limpiarComentario(texto, entradaJson) {
  const digitos = (t) => (String(t).match(/\d[\d.,]*/g) || []).map((n) => n.replace(/\D/g, '')).filter(Boolean);
  const conocidas = new Set(digitos(entradaJson));
  let eliminadas = 0;
  const lineas = sinGuiones(texto).trim().split('\n').map((linea) => {
    if (/^\s*#/.test(linea)) return linea;
    return linea.split(/(?<=[.!?])\s+/).filter((frase) => { const raras = digitos(frase).filter((d) => !conocidas.has(d)); if (raras.length) { eliminadas++; return false; } return true; }).join(' ');
  });
  let out = lineas.join('\n').trim();
  if (eliminadas) out += `\n\n> Nota del sistema: se eliminaron ${eliminadas} frase(s) del comentario por contener cifras que no estaban en los datos calculados.`;
  return out;
}

// Nodo "Armar informe": junta los calculos con el comentario de Claude (si hubo) y prepara los archivos.
const calc = $('Calcular inventario').first().json;
let textoIA = '';
let usoIA = null;
try {
  const r = $('Claude: comentario').first().json;
  textoIA = r && r.content && r.content[0] ? String(r.content[0].text || '') : '';
  usoIA = r && r.usage ? r.usage : null;
} catch (e) { /* no se uso IA en esta corrida */ }

const comentario = textoIA ? limpiarComentario(textoIA, calc.entrada_ia) : '';
const uso = usoIA ? { llamadas: 1, entrada: usoIA.input_tokens || 0, salida: usoIA.output_tokens || 0, costo: ((usoIA.input_tokens || 0) * PRECIO_MTOK.entrada + (usoIA.output_tokens || 0) * PRECIO_MTOK.salida) / 1e6 } : null;
const inf = armarInforme({ res: calc.res, ind: calc.ind, cfg: calc.cfg, comentario, uso, tiempos: calc.ms });

const base = `${CARPETA_INFORMES}\\inventario_${calc.res.ym}`;
const salidaChat = `${inf.chat}\n\nInforme completo (tablas, indicadores y supuestos): ${base}.html\nPedido sugerido para Excel: ${base}_pedido.csv`;
const bin = async (contenido, nombre, mime) => this.helpers.prepareBinaryData(Buffer.from(contenido, 'utf8'), nombre, mime);

return [
  { json: { ruta: `${base}.html`, output: salidaChat }, binary: { data: await bin(inf.html, 'informe.html', 'text/html') } },
  { json: { ruta: `${base}.md`, output: salidaChat }, binary: { data: await bin(inf.md, 'informe.md', 'text/markdown') } },
  { json: { ruta: `${base}_pedido.csv`, output: salidaChat }, binary: { data: await bin(inf.csvPedido, 'pedido.csv', 'text/csv') } },
  { json: { ruta: `${base}_detalle.csv`, output: salidaChat }, binary: { data: await bin(inf.csvDetalle, 'detalle.csv', 'text/csv') } },
];
